(function(root) {
    const DOOR_OPEN_TIME = 0.8;
    const DOOR_CLOSE_TIME = 1.2;
    const MIN_DOOR_OPEN_S = 1.5;
    const MAX_DOOR_OPEN_S = 12;
    const MOVE_SPEED = 2.0; // floors per second

    class ElevatorLogic {
        constructor({floorCount = 6, maxCapacity = 4, floorHeight = 3.4} = {}) {
            this.floorCount = floorCount;
            this.maxCapacity = maxCapacity;
            this.floorHeight = floorHeight;
            this.reset();
        }

        reset() {
            this.state = 'IDLE';
            this.direction = 0;
            this.currentFloor = 0;
            this.targetFloor = null;
            this.upCalls = new Set();
            this.downCalls = new Set();
            this.destinations = new Set();
            this.passengers = new Set();
            this.pendingBoarders = new Set();
            this.pendingDisembark = new Set();
            this.spotOccupancy = [false, false, false, false];
            this._doorTimer = 0;
            this._moveProgress = 0;
            this._lastServedFloor = -1;
        }

        callUp(floor) {
            if (floor < this.floorCount - 1) this.upCalls.add(floor);
        }

        callDown(floor) {
            if (floor > 0) this.downCalls.add(floor);
        }

        pressDestination(floor) {
            if (floor >= 0 && floor < this.floorCount && floor !== this.currentFloor) {
                this.destinations.add(floor);
            }
        }

        isAcceptingAt(floor, direction) {
            if (this.state !== 'DOOR_OPEN' || this.currentFloor !== Math.round(this.currentFloor)) return false;
            if (Math.abs(this.currentFloor - floor) > 0.01) return false;
            // True if no more stops in current direction OR caller direction matches car direction
            const hasStopsInDirection = this._hasWorkInDirection(this.direction);
            if (!hasStopsInDirection) return true;
            return direction === this.direction || this.direction === 0;
        }

        _hasWorkInDirection(dir) {
            if (dir === 0) return this.destinations.size > 0 || this.upCalls.size > 0 || this.downCalls.size > 0;
            const cf = this.currentFloor;
            if (dir > 0) {
                for (let f = cf + 1; f < this.floorCount; f++) {
                    if (this.destinations.has(f) || this.upCalls.has(f) || this.downCalls.has(f)) return true;
                }
            } else {
                for (let f = cf - 1; f >= 0; f--) {
                    if (this.destinations.has(f) || this.upCalls.has(f) || this.downCalls.has(f)) return true;
                }
            }
            return false;
        }

        currentCapacityFree() {
            return this.maxCapacity - (this.passengers.size + this.pendingBoarders.size);
        }

        reserveBoardingSpot(person) {
            const free = this.currentCapacityFree();
            if (free <= 0) return null;
            // Find a free spot
            for (let i = 0; i < 4; i++) {
                if (!this.spotOccupancy[i]) {
                    this.spotOccupancy[i] = true;
                    this.pendingBoarders.add(person);
                    const xOff = (i % 2 === 0 ? -0.7 : 0.7);
                    const zOff = (i < 2 ? 0.5 : -0.5);
                    return { index: i, x: xOff, y: 0, z: zOff };
                }
            }
            return null;
        }

        completeBoard(person) {
            this.pendingBoarders.delete(person);
            this.passengers.add(person);
        }

        registerDisembark(person) {
            this.pendingDisembark.add(person);
        }

        completeDisembark(person) {
            this.pendingDisembark.delete(person);
            this.passengers.delete(person);
            // Release the spot
            // We need to track which spot each passenger has. Let me add a map.
            const idx = this._passengerSpots.get(person);
            if (idx !== undefined) {
                this.spotOccupancy[idx] = false;
                this._passengerSpots.delete(person);
            }
        }

        tick(dt) {
            switch (this.state) {
                case 'IDLE':
                    this._pickTargetAndMove();
                    break;
                case 'MOVING':
                    this._tickMoving(dt);
                    break;
                case 'DOOR_OPENING':
                    this._doorTimer += dt;
                    if (this._doorTimer >= DOOR_OPEN_TIME) {
                        this._doorTimer = 0;
                        this.state = 'DOOR_OPEN';
                        this._doorOpenDuration = 0;
                        // Serve calls at this floor
                        this._serveCurrentFloor();
                    }
                    break;
                case 'DOOR_OPEN':
                    this._doorOpenDuration += dt;
                    // Check if we can close
                    if (this.pendingBoarders.size === 0 && this.pendingDisembark.size === 0) {
                        if (this._doorOpenDuration >= MIN_DOOR_OPEN_S) {
                            this._startClosing();
                        }
                    }
                    // Safety cap
                    if (this._doorOpenDuration >= MAX_DOOR_OPEN_S) {
                        // Force clear pending sets
                        this.pendingBoarders.clear();
                        this.pendingDisembark.clear();
                        this._startClosing();
                    }
                    break;
                case 'DOOR_CLOSING':
                    this._doorTimer += dt;
                    if (this._doorTimer >= DOOR_CLOSE_TIME) {
                        this._doorTimer = 0;
                        this._pickTargetAndMove();
                    }
                    break;
            }
        }

        _serveCurrentFloor() {
            const cf = this.currentFloor;
            this.destinations.delete(cf);
            // Clear hall call in current direction
            if (this.direction > 0) {
                this.upCalls.delete(cf);
            } else if (this.direction < 0) {
                this.downCalls.delete(cf);
            }
            // If no more stops in current direction, also clear opposite call
            if (!this._hasWorkInDirection(this.direction)) {
                if (this.direction > 0) {
                    this.downCalls.delete(cf);
                } else if (this.direction < 0) {
                    this.upCalls.delete(cf);
                }
            }
            this._lastServedFloor = cf;
        }

        _startClosing() {
            this.state = 'DOOR_CLOSING';
            this._doorTimer = 0;
        }

        _pickTargetAndMove() {
            const target = this._selectTarget();
            if (target === null) {
                this.state = 'IDLE';
                this.direction = 0;
                this.targetFloor = null;
                return;
            }
            this.targetFloor = target;
            this.direction = target > this.currentFloor ? 1 : (target < this.currentFloor ? -1 : 0);
            if (this.direction === 0) {
                // We're already at the target floor, just open doors
                this.state = 'DOOR_OPENING';
                this._doorTimer = 0;
                return;
            }
            this.state = 'MOVING';
            this._moveProgress = 0;
        }

        _selectTarget() {
            const cf = this.currentFloor;

            // Gather all candidate floors
            const allCandidates = new Set();
            for (const d of this.destinations) allCandidates.add(d);
            for (const u of this.upCalls) allCandidates.add(u);
            for (const d of this.downCalls) allCandidates.add(d);

            if (allCandidates.size === 0) return null;

            // If we have passengers, prioritize their destinations
            const hasPassengers = this.passengers.size > 0;

            // Continue in current direction
            if (this.direction !== 0) {
                const ahead = [];
                const behind = [];
                for (const f of allCandidates) {
                    if (this.direction > 0 && f > cf) ahead.push(f);
                    else if (this.direction < 0 && f < cf) ahead.push(f);
                    else if (this.direction > 0 && f < cf) behind.push(f);
                    else if (this.direction < 0 && f > cf) behind.push(f);
                    // f === cf: same floor
                }

                // Check ahead first
                if (ahead.length > 0) {
                    ahead.sort((a, b) => this.direction > 0 ? a - b : b - a);
                    // If we just served this floor and have passengers, skip same-floor calls
                    for (const f of ahead) {
                        if (f === cf && this._lastServedFloor === cf && hasPassengers) continue;
                        return f;
                    }
                }

                // Nothing ahead, reverse
                if (behind.length > 0) {
                    behind.sort((a, b) => this.direction > 0 ? b - a : a - b);
                    return behind[0];
                }

                // Only same-floor candidates left
                const sameFloor = [...allCandidates].filter(f => f === cf);
                if (sameFloor.length > 0 && !(this._lastServedFloor === cf && hasPassengers)) {
                    return cf;
                }

                return null;
            }

            // IDLE: pick nearest
            let nearest = null;
            let nearestDist = Infinity;
            for (const f of allCandidates) {
                const dist = Math.abs(f - cf);
                if (dist < nearestDist) {
                    nearestDist = dist;
                    nearest = f;
                }
            }
            return nearest;
        }

        _tickMoving(dt) {
            this._moveProgress += dt * MOVE_SPEED * this.floorHeight;

            // Re-evaluate target: check for closer stops in same direction
            if (this._moveProgress < this.floorHeight * 0.5) {
                // Only re-evaluate early in the journey
                const closerTarget = this._findCloserTarget();
                if (closerTarget !== null && closerTarget !== this.targetFloor) {
                    this.targetFloor = closerTarget;
                }
            }

            if (this._moveProgress >= this.floorHeight) {
                // Arrive at next floor
                this._moveProgress = 0;
                this.currentFloor += this.direction;
                this.currentFloor = Math.max(0, Math.min(this.floorCount - 1, this.currentFloor));

                if (this.currentFloor === this.targetFloor) {
                    // Arrived
                    this.state = 'DOOR_OPENING';
                    this._doorTimer = 0;
                }
                // Otherwise continue moving toward target
            }
        }

        _findCloserTarget() {
            // During MOVING, check if there's a call/destination at the next floor
            // in our direction that we should stop at
            const nextFloor = this.currentFloor + this.direction;
            if (nextFloor < 0 || nextFloor >= this.floorCount) return null;

            if (this.destinations.has(nextFloor)) return nextFloor;
            if (this.direction > 0 && this.upCalls.has(nextFloor)) return nextFloor;
            if (this.direction < 0 && this.downCalls.has(nextFloor)) return nextFloor;

            return null;
        }
    }

