(function(root) {
    const DOOR_OPEN_TIME = 0.8;
    const DOOR_CLOSE_TIME = 1.2;
    const MIN_DOOR_OPEN_S = 1.5;
    const MAX_DOOR_OPEN_S = 12;
    const MOVE_SPEED = 2.0;

    class ElevatorLogic {
        constructor({floorCount = 6, maxCapacity = 4, floorHeight = 3.4} = {}) {
            this.floorCount = floorCount;
            this.maxCapacity = maxCapacity;
            this.floorHeight = floorHeight;
            this.reset();
        }

        reset() {
            this.state = 'IDLE';
            this.direction = 0;
            this.currentFloor = 0;
            this.targetFloor = null;
            this.upCalls = new Set();
            this.downCalls = new Set();
            this.destinations = new Set();
            this.passengers = new Set();
            this.pendingBoarders = new Set();
            this.pendingDisembark = new Set();
            this.spotOccupancy = [false, false, false, false];
            this._boardingSpots = new Map();
            this._doorTimer = 0;
            this._doorOpenDuration = 0;
            this._moveProgress = 0;
            this._lastServedFloor = -1;
        }

        callUp(floor) {
            if (floor >= 0 && floor < this.floorCount - 1) {
                this.upCalls.add(floor);
            }
        }

        callDown(floor) {
            if (floor > 0 && floor < this.floorCount) {
                this.downCalls.add(floor);
            }
        }

        pressDestination(floor) {
            if (floor >= 0 && floor < this.floorCount) {
                this.destinations.add(floor);
            }
        }

        isAcceptingAt(floor, direction) {
            if (this.state !== 'DOOR_OPEN') return false;
            if (Math.abs(this.currentFloor - floor) > 0.01) return false;
            if (direction === 0) return true;
            if (this.direction === 0) return true;
            if (direction === this.direction) return true;
            // Accept opposite direction if no more work ahead
            return !this._hasWorkInDirection(this.direction);
        }

        _hasWorkInDirection(dir) {
            if (dir === 0) return false;
            const cf = this.currentFloor;
            if (dir > 0) {
                for (let f = cf + 1; f < this.floorCount; f++) {
                    if (this.destinations.has(f) || this.upCalls.has(f) || this.downCalls.has(f)) {
                        return true;
                    }
                }
            } else {
                for (let f = cf - 1; f >= 0; f--) {
                    if (this.destinations.has(f) || this.upCalls.has(f) || this.downCalls.has(f)) {
                        return true;
                    }
                }
            }
            return false;
        }

        currentCapacityFree() {
            return this.maxCapacity - (this.passengers.size + this.pendingBoarders.size);
        }

        reserveBoardingSpot(person) {
            if (this.currentCapacityFree() <= 0) return null;
            for (let i = 0; i < 4; i++) {
                if (!this.spotOccupancy[i]) {
                    this.spotOccupancy[i] = true;
                    this.pendingBoarders.add(person);
                    this._boardingSpots.set(person, i);
                    var xOff = (i % 2 === 0 ? -0.7 : 0.7);
                    var zOff = (i < 2 ? 0.5 : -0.5);
                    return { index: i, x: xOff, y: 0, z: zOff };
                }
            }
            return null;
        }

        completeBoard(person) {
            this.pendingBoarders.delete(person);
            this.passengers.add(person);
        }

        registerDisembark(person) {
            this.pendingDisembark.add(person);
        }

        completeDisembark(person) {
            this.pendingDisembark.delete(person);
            this.passengers.delete(person);
            var idx = this._boardingSpots.get(person);
            if (idx !== undefined) {
                this.spotOccupancy[idx] = false;
                this._boardingSpots.delete(person);
            }
        }

        tick(dt) {
            var self = this;
            switch (self.state) {
                case 'IDLE':
                    self._pickTargetAndMove();
                    break;
                case 'MOVING':
                    self._tickMoving(dt);
                    break;
                case 'DOOR_OPENING':
                    self._doorTimer += dt;
                    if (self._doorTimer >= DOOR_OPEN_TIME) {
                        self._doorTimer = 0;
                        self.state = 'DOOR_OPEN';
                        self._doorOpenDuration = 0;
                        self._serveCurrentFloor();
                    }
                    break;
                case 'DOOR_OPEN':
                    self._doorOpenDuration += dt;
                    if (self.pendingBoarders.size === 0 && self.pendingDisembark.size === 0) {
                        if (self._doorOpenDuration >= MIN_DOOR_OPEN_S) {
                            self._startClosing();
                            break;
                        }
                    }
                    if (self._doorOpenDuration >= MAX_DOOR_OPEN_S) {
                        self.pendingBoarders.clear();
                        self.pendingDisembark.clear();
                        self._startClosing();
                    }
                    break;
                case 'DOOR_CLOSING':
                    self._doorTimer += dt;
                    if (self._doorTimer >= DOOR_CLOSE_TIME) {
                        self._doorTimer = 0;
                        self._pickTargetAndMove();
                    }
                    break;
            }
        }

        _serveCurrentFloor() {
            var cf = this.currentFloor;
            this.destinations.delete(cf);
            if (this.direction > 0) {
                this.upCalls.delete(cf);
            } else if (this.direction < 0) {
                this.downCalls.delete(cf);
            }
            if (!this._hasWorkInDirection(this.direction)) {
                if (this.direction > 0) {
                    this.downCalls.delete(cf);
                } else if (this.direction < 0) {
                    this.upCalls.delete(cf);
                }
            }
            this._lastServedFloor = cf;
        }

        _startClosing() {
            this.state = 'DOOR_CLOSING';
            this._doorTimer = 0;
        }

        _pickTargetAndMove() {
            var target = this._selectTarget();
            if (target === null) {
                this.state = 'IDLE';
                this.direction = 0;
                this.targetFloor = null;
                return;
            }
            if (target === this.currentFloor) {
                this.targetFloor = target;
                this.direction = 0;
                this.state = 'DOOR_OPENING';
                this._doorTimer = 0;
                return;
            }
            this.targetFloor = target;
            this.direction = target > this.currentFloor ? 1 : -1;
            this.state = 'MOVING';
            this._moveProgress = 0;
        }

        _selectTarget() {
            var cf = this.currentFloor;
            var allCandidates = new Set();
            var self = this;
            self.destinations.forEach(function(f) { allCandidates.add(f); });
            self.upCalls.forEach(function(f) { allCandidates.add(f); });
            self.downCalls.forEach(function(f) { allCandidates.add(f); });

            if (allCandidates.size === 0) return null;

            var hasPassengers = self.passengers.size > 0;

            if (self.direction !== 0) {
                var ahead = [];
                var behind = [];
                allCandidates.forEach(function(f) {
                    if (self.direction > 0 && f > cf) ahead.push(f);
                    else if (self.direction < 0 && f < cf) ahead.push(f);
                    else if (f !== cf) behind.push(f);
                });

                // Check ahead first
                if (ahead.length > 0) {
                    ahead.sort(function(a, b) { return self.direction > 0 ? a - b : b - a; });
                    return ahead[0];
                }

                // Nothing ahead, reverse
                if (behind.length > 0) {
                    behind.sort(function(a, b) { return self.direction > 0 ? b - a : a - b; });
                    return behind[0];
                }

                // Only same-floor candidates left
                if (allCandidates.has(cf)) {
                    if (!(self._lastServedFloor === cf && hasPassengers)) {
                        return cf;
                    }
                }

                return null;
            }

            // IDLE: pick nearest
            var nearest = null;
            var nearestDist = Infinity;
            allCandidates.forEach(function(f) {
                var dist = Math.abs(f - cf);
                if (dist < nearestDist) {
                    nearestDist = dist;
                    nearest = f;
                }
            });
            return nearest;
        }

        _tickMoving(dt) {
            var self = this;
            self._moveProgress += dt * MOVE_SPEED * self.floorHeight;

            // Re-evaluate: check for a closer stop at next floor
            var ct = self._findCloserTarget();
            if (ct !== null && ct !== self.targetFloor && ct !== self.currentFloor) {
                self.targetFloor = ct;
            }

            while (self._moveProgress >= self.floorHeight) {
                self._moveProgress -= self.floorHeight;
