The key insight: "Passenger destinations outrank same-floor hall calls." So when passengers have destinations, we should look at destinations first, then hall calls.

Here's my revised approach:

```js
_selectTarget() {
    var cf = this.currentFloor;
    var dir = this.direction;
    var hasPassengers = this.passengers.size > 0;

    // If we have passengers, prioritize their destinations
    if (hasPassengers && this.destinations.size > 0) {
        // Look for destinations ahead in current direction
        if (dir > 0) {
            for (var f = cf + 1; f < this.floorCount; f++) {
                if (this.destinations.has(f)) return f;
            }
        } else if (dir < 0) {
            for (var f = cf - 1; f >= 0; f--) {
                if (this.destinations.has(f)) return f;
            }
        }
        // No destinations in current direction, reverse
        if (dir > 0) {
            for (var f = cf - 1; f >= 0; f--) {
                if (this.destinations.has(f)) return f;
            }
        } else if (dir < 0) {
            for (var f = cf + 1; f < this.floorCount; f++) {
                if (this.destinations.has(f)) return f;
            }
        }
        // IDLE with passengers: pick nearest destination
        if (dir === 0) {
            var best = null, bestD = Infinity;
            this.destinations.forEach(function(f) {
                var d = Math.abs(f - cf);
                if (d < bestD) { bestD = d; best = f; }
            });
            if (best !== null) return best;
        }
    }

    // Then consider hall calls
    // Build candidate set from hall calls + remaining destinations
    var candidates = new Set();
    this.destinations.forEach(function(f) { candidates.add(f); });
    this.upCalls.forEach(function(f) { candidates.add(f); });
    this.downCalls.forEach(function(f) { candidates.add(f); });

    if (candidates.size === 0) return null;

    if (dir !== 0) {
        // Look ahead in current direction
        var ahead = [];
        candidates.forEach(function(f) {
            if (dir > 0 && f > cf) ahead.push(f);
            else if (dir < 0 && f < cf) ahead.push(f);
        });
        if (ahead.length > 0) {
            ahead.sort(function(a,b) { return dir > 0 ? a - b : b - a; });
            return ahead[0];
        }
        // Reverse
        var behind = [];
        candidates.forEach(function(f) {
            if (dir > 0 && f < cf) behind.push(f);
            else if (dir < 0 && f > cf) behind.push(f);
        });
        if (behind.length > 0) {
            behind.sort(function(a,b) { return dir > 0 ? b - a : a - b; });
            return behind[0];
        }
        // Same floor candidates
        if (candidates.has(cf) && !(this._lastServedFloor === cf && hasPassengers)) {
            return cf;
        }
        return null;
    }

    // IDLE: pick nearest
    var nearest = null, nearestD = Infinity;
    candidates.forEach(function(f) {
        var d = Math.abs(f - cf);
        if (d < nearestD) { nearestD = d; nearest = f; }
    });
    return nearest;
}
```

