const assert = require("assert");
const { ElevatorLogic } = require("./elevator_logic.js");

let passed = 0;
let failed = 0;

function test(name, fn) {
    try {
        fn();
        passed++;
        console.log("  PASS: " + name);
    } catch (e) {
        failed++;
        console.log("  FAIL: " + name + " - " + e.message);
    }
}

function tickUntil(elevator, predicate, maxTicks) {
    maxTicks = maxTicks || 2000;
    for (var i = 0; i < maxTicks; i++) {
        elevator.tick(0.016);
        if (predicate(elevator)) return true;
    }
    return false;
}

function tickUntilDoorOpen(elevator, maxTicks) {
    return tickUntil(elevator, function(el) { return el.state === 'DOOR_OPEN'; }, maxTicks);
}

function tickUntilDoorClosed(elevator, maxTicks) {
    return tickUntil(elevator, function(el) { return el.state !== 'DOOR_OPEN' && el.state !== 'DOOR_OPENING' && el.state !== 'DOOR_CLOSING'; }, maxTicks);
}

function tickUntilState(elevator, state, maxTicks) {
    return tickUntil(elevator, function(el) { return el.state === state; }, maxTicks);
}

// ============================================================
// Test 1: Lobby rush with more callers than capacity
// ============================================================
test("Lobby rush: full car leaves floor 0 despite leftover UP calls", function() {
    var el = new ElevatorLogic({floorCount: 6, maxCapacity: 4, floorHeight: 3.4});

    // Call up at floor 0
    el.callUp(0);
    assert.ok(tickUntilDoorOpen(el), "Should open doors at floor 0");

    // Board 4 people
    for (var i = 0; i < 4; i++) {
        var spot = el.reserveBoardingSpot("p" + i);
        assert.ok(spot !== null, "Should reserve spot " + i);
        el.completeBoard("p" + i);
    }

    // Press destinations
    el.pressDestination(3);
    el.pressDestination(5);

    // Tick until doors start closing or moving
    assert.ok(tickUntilState(el, 'DOOR_CLOSING'), "Should start closing");

    // While closing, leftover waiters press UP
    el.callUp(0);

    // Tick until car moves or reaches next state
    assert.ok(tickUntil(el, function(e) { return e.state === 'MOVING' || e.state === 'DOOR_OPENING'; }), "Should transition");

    // The target must NOT be floor 0
    if (el.state === 'MOVING' || el.targetFloor !== null) {
        assert.notStrictEqual(el.targetFloor, 0, "Target should not be floor 0 when full car has destinations");
    }
});

// ============================================================
// Test 2: Passenger destinations outrank same-floor hall calls
// ============================================================
test("Passenger destinations outrank same-floor hall calls", function() {
    var el = new ElevatorLogic({floorCount: 6, maxCapacity: 4, floorHeight: 3.4});

    // Get car to floor 2 with a passenger
    el.callUp(0);
    assert.ok(tickUntilDoorOpen(el), "Should open at floor 0");
    el.reserveBoardingSpot("p1");
    el.completeBoard("p1");
    el.pressDestination(4);
    assert.ok(tickUntilState(el, 'DOOR_CLOSING'), "Should close doors");

    // Move to floor 2 (intermediate stop via _findCloserTarget won't trigger since no call at 2)
    // Actually let me add a call at floor 2 so it stops
    el.callUp(2);
    assert.ok(tickUntilDoorOpen(el), "Should open at floor 2");

    // At floor 2 with doors open and a passenger on board heading to 4
    // Add a same-floor hall call (UP at floor 2)
    // This should NOT cause an immediate reopen after doors close
    el.callUp(2);

    // Wait for doors to close and car to decide next target
    assert.ok(tickUntilState(el, 'DOOR_CLOSING'), "Should close doors");

    // Now tick until it moves or opens doors
    tickUntil(el, function(e) { return e.state === 'MOVING' || e.state === 'DOOR_OPENING'; });

    // Should be heading to floor 4 (passenger destination), not reopening at floor 2
    if (el.state === 'MOVING') {
        assert.strictEqual(el.targetFloor, 4, "Should target passenger destination (4), not same-floor call (2)");
    }
});

// ============================================================
// Test 3: Repeated hall-call pressing cannot starve riders
// ============================================================
test("Repeated hall-call pressing cannot starve riders", function() {
    var el = new ElevatorLogic({floorCount: 6, maxCapacity: 4, floorHeight: 3.4});

    // Board a passenger at floor 0 going to floor 3
    el.callUp(0);
    assert.ok(tickUntilDoorOpen(el), "Should open at floor 0");
    el.reserveBoardingSpot("p1");
    el.completeBoard("p1");
    el.pressDestination(3);
    assert.ok(tickUntilState(el, 'DOOR_CLOSING'), "Should close doors");

    // Now repeatedly call UP at floor 0 across several ticks
    for (var i = 0; i < 50; i++) {
        el.callUp(0);
        el.tick(0.016);
    }

    // Car should eventually reach floor 3 (the passenger destination)
    var reached = tickUntil(el, function(e) { return e.currentFloor >= 3 && e.state === 'DOOR_OPEN'; }, 3000);
    assert.ok(reached, "Car should eventually reach passenger destination floor 3");
});

// ============================================================
// Test 4: Opposite-direction calls wait their turn
// ============================================================
test("Opposite-direction calls wait their turn", function() {
    var el = new ElevatorLogic({floorCount: 6, maxCapacity: 4, floorHeight: 3.4});

    // Call UP at floor 0
    el.callUp(0);
    assert.ok(tickUntilDoorOpen(el), "Should open at floor 0");
    el.reserveBoardingSpot("p1");
    el.completeBoard("p1");
    el.pressDestination(5);
    assert.ok(tickUntilState(el, 'DOOR_CLOSING'), "Should close doors");

    // While moving up, add a DOWN call at floor 4
    // This should be served on the way up (it's ahead in same direction)
    el.callDown(4);

    // Let it run: should reach floor 4 (the DOWN call ahead in UP direction)
    assert.ok(tickUntil(el, function(e) { return e.currentFloor === 4 && e.state === 'DOOR_OPEN'; }, 3000), "Should stop at floor 4 for down call on way up");

    // Now add a DOWN call at floor 2 - this should NOT reverse the car
    el.callDown(2);
    assert.ok(tickUntilState(el, 'DOOR_CLOSING'), "Should close doors");
    tickUntil(el, function(e) { return e.state === 'MOVING' || e.state === 'DOOR_OPENING'; });

    // Should continue up to 5, not reverse to 2
    assert.ok(el.direction === 1 || el.targetFloor === 5, "Should continue upward, not reverse for floor 2");
});

// ============================================================
// Test 5: Door hold and safety cap
// ============================================================
test("Door hold: pending boarders keep doors open; MAX_DOOR_OPEN_S fires", function() {
    var el = new ElevatorLogic({floorCount: 6, maxCapacity: 4, floorHeight: 3.4});

    el.callUp(0);
    assert.ok(tickUntilDoorOpen(el), "Should open at floor 0");

    // Reserve a spot but never completeBoard - simulates a slow boarder
    el.reserveBoardingSpot("slow_person");

    // Tick for a while - doors should stay open beyond MIN_DOOR_OPEN_S
    for (var i = 0; i < 100; i++) {
        el.tick(0.016);
    }
    assert.strictEqual(el.state, 'DOOR_OPEN', "Doors should stay open with pending boarder");

    // Now tick past MAX_DOOR_OPEN_S
    for (var j = 0; j < 800; j++) {
        el.tick(0.016);
    }
    // Doors should have closed by now (MAX_DOOR_OPEN_S safety cap)
    assert.notStrictEqual(el.state, 'DOOR_OPEN', "Doors should close after MAX_DOOR_OPEN_S");
});

// ============================================================
// Test 6: Destination preserved across the action handshake
// ============================================================
test("Destination preserved: floor 5 destination not inferred as floor 1", function() {
    var el = new ElevatorLogic({floorCount: 6, maxCapacity: 4, floorHeight: 3.4});

    // Call up at floor 0
    el.callUp(0);
    assert.ok(tickUntilDoorOpen(el), "Should open at floor 0");

    // Verify it's accepting at floor 0 going UP
    assert.ok(el.isAcceptingAt(0, 1), "Should accept UP at floor 0");

    // Board and press destination 5
    el.reserveBoardingSpot("rider");
    el.completeBoard("rider");
    el.pressDestination(5);

    assert.ok(el.destinations.has(5), "Should have destination 5 in set");

    // Close doors and move
    assert.ok(tickUntilState(el, 'DOOR_CLOSING'), "Should close doors");
    assert.ok(tickUntil(el, function(e) { return e.state === 'MOVING'; }), "Should start moving");

    // Car should be moving toward floor 5, not floor 1
    assert.strictEqual(el.direction, 1, "Direction should be up");
    assert.ok(el.targetFloor >= 5 || el.destinations.has(5) || el.passengers.has("rider"), "Should target floor 5, not floor 1 from direction alone");

    // Let it run to completion - should arrive at floor 5
    var arrivedAt5 = tickUntil(el, function(e) { return e.currentFloor === 5 && e.state === 'DOOR_OPEN'; }, 3000);
    assert.ok(arrivedAt5, "Should eventually arrive at floor 5");
});

// ============================================================
// Test 7: Reset clears phantom state
// ============================================================
test("Reset clears phantom state", function() {
    var el = new ElevatorLogic({floorCount: 6, maxCapacity: 4, floorHeight: 3.4});

    // Put elevator in a busy state
    el.callUp(0);
    el.callDown(3);
    assert.ok(tickUntilDoorOpen(el), "Should open at floor 0");
    el.reserveBoardingSpot("p1");
    el.completeBoard("p1");
    el.reserveBoardingSpot("p2");
    el.completeBoard("p2");
    el.pressDestination(4);
    el.pressDestination(2);

    // Reset
    el.reset();

    // Verify clean state
    assert.strictEqual(el.state, 'IDLE');
    assert.strictEqual(el.direction, 0);
    assert.strictEqual(el.currentFloor, 0);
    assert.strictEqual(el.targetFloor, null);
    assert.strictEqual(el.upCalls.size, 0);
    assert.strictEqual(el.downCalls.size, 0);
    assert.strictEqual(el.destinations.size, 0);
    assert.strictEqual(el.passengers.size, 0);
    assert.strictEqual(el.pendingBoarders.size, 0);
    assert.strictEqual(el.pendingDisembark.size, 0);
    assert.strictEqual(el._boardingSpots.size, 0);
    for (var i = 0; i < 4; i++) {
        assert.strictEqual(el.spotOccupancy[i], false, "Spot " + i + " should be free");
    }
});

// ============================================================
// Summary
// ============================================================
console.log("\n" + (passed + failed) + " tests: " + passed + " passed, " + failed + " failed");
if (failed > 0) {
    process.exit(1);
